import type { Locale } from '@/lib/i18n'

// Juridische pagina's (Terms, Privacy, Refund, Cookie) in 7 talen.
// Best practice (internationale SaaS): vertaling beschikbaar in elke taal + "Engelse versie is bindend"-clausule.
// De Engelse tekst is de authoritatieve versie; vertalingen zijn ter beschikking voor het gemak van de klant.

export type Block =
  | { t: 'box'; title: string; text: string }
  | { t: 'h2'; text: string }
  | { t: 'p'; text: string }
  | { t: 'pb'; text: string } // bold paragraph
  | { t: 'ul'; items: string[] }
  | { t: 'dl'; items: [string, string][] } // term, description
  | { t: 'contact'; pre: string; email: string; post?: string }
  | { t: 'linkline'; pre: string; linkText: string; href: string; post: string }
  | { t: 'table'; head: [string, string, string]; rows: [string, string, string][] }

export interface LegalContent { title: string; blocks: Block[] }

